mapper.select:
SELECT r.*, COUNT(ri.id) AS pad_count FROM pad_mold_reserve_record r LEFT JOIN pad_mold_reserve_item ri ON ri.reserve_id = r.id
AND r.status = #{query.status}
AND (r.mold_code LIKE CONCAT('%', #{query.moldCode}, '%') OR r.mold_name LIKE CONCAT('%', #{query.moldCode}, '%'))
AND r.operator LIKE CONCAT('%', #{query.operator}, '%')
AND EXISTS (SELECT 1 FROM pad_mold_reserve_item cri WHERE cri.reserve_id = r.id AND cri.pad_code LIKE CONCAT('%', #{query.padCode}, '%'))
AND r.start_time >= #{query.startTime}
AND r.start_time <= #{query.endTime}
GROUP BY r.id ORDER BY r.start_time DESC, r.id DESC

mapper.update:
UPDATE pad_mold_reserve_record
SET status = 'ACTIVE', update_time = #{now}
WHERE status = 'PENDING' AND start_time <= #{now} AND end_time >= #{now}
